// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// Shape of TIME


let scale;
let t = 0;
let mySize;

// colors without alpha
const palettes = [
	["#4596c7", "#6d8370", "#e45240", "#21d3a4", "#3303f9"],
	["#b8dbcc", "#472433", "#e1fff6", "#e3b0c8", "#212523"],
	["#ffffff", "#292929", "#000000", "#f7fcfe", "#14001a"],
	["#5d565c", "#b41a1d", "#c0dee4", "#edb136", "#e07958"],
	["#add8e6", "#9fb7f4", "#12177d", "#9bb5e9", "#e4f2f7"],
	["#1b1b1b", "#292929", "#f3f3f3", "#222222", "#ff0000"],
	["#eda492", "#d59c95", "#af3918", "#d9b6b5", "#853532"],
	["#f86fcd", "#97d183", "#240ce8", "#b0e298", "#7f37e8"],
	["#2E294E", "#541388", "#F1E9DA", "#FFD400", "#D90368"],
	["#e9baaa", "#ffa07a", "#164555", "#ffe1d0", "#acd9e7"]
]


let Central_Star = Math.random() * 8723;
let Nebula_Rings;
let Star_Amount;
let Nebula_Color;
let Turbulence;
let Nebula_Size;
let Stars_Tail;
let Stars_Size;

function setup() {
	randomSeed(Central_Star);
	noiseSeed(Central_Star);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	background(266, 50, 5, 100);
	noFill();
	scale = 1;
	Nebula_Rings = int(random(30, 60));
	Star_Amount = int(random(10, 60));
	Nebula_Color = int(random(palettes.length - 1));
	Turbulence = int(random(2, 20));
	Nebula_Size = mySize / 2;
	Stars_Tail = int(random(2,7));
}

function draw() {
	randomSeed(Central_Star);
	noiseSeed(Central_Star);
	background(266, 50, 5, Stars_Tail);
	push();
	translate(width / 2, height / 2);


	for (let r = 0; r < Nebula_Size; r += Nebula_Size / Nebula_Rings) {
		stroke(random(palettes[Nebula_Color]));
		strokeCap(ROUND);
		let o_angle = random(TAU);
		rotate(o_angle + t);

		// blendMode(LIGHTEST);
		for (
			let a = -TAU / Star_Amount; a < TAU + TAU / Star_Amount; a += TAU / Star_Amount
		) {
			let x = r * cos(a);
			let y = r * sin(a);
			let n = map(noise(x * (Turbulence / 1000), y * (Turbulence / 1000)), 0, 1, -0, scale);
			stroke(random(palettes[Nebula_Color]));
			n = random(n / 1, n / 4);
			Stars_Size = random(30);

			strokeWeight(random(0.1 * (Stars_Size - r / 100)));
			point(x * (1 + random(-n, n)), y * (1 + random(-n, n)));

		}
	}
	pop();
	t += TAU / 36000 / 5;
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("Shape of TIME_Circle Startail", "png");
	}
}

